return items.map((item, index) => {
  const rssItem = item.json;
  const titleCandidate = rssItem.title || rssItem.creator || rssItem.guid || rssItem.link || 'Untitled';
  const title = typeof titleCandidate === 'string' ? titleCandidate : String(titleCandidate);
  const urlCandidate = rssItem.link || rssItem.guid || '';
  const url = typeof urlCandidate === 'string' ? urlCandidate : String(urlCandidate);
  const publishedAtRaw = rssItem.isoDate || rssItem.pubDate || null;
  const publishedAt = publishedAtRaw instanceof Date ? publishedAtRaw.toISOString() : publishedAtRaw;

  if (!url) {
    return null;
  }

  const rawSourceId = $('Expand Sources').itemMatching(index).json.id;
  const sourceId = Number.parseInt(String(rawSourceId), 10);

  if (!Number.isFinite(sourceId)) {
    return null;
  }

  const author = typeof rssItem.creator === 'string' ? rssItem.creator : null;
  const rawExcerptCandidate = rssItem.contentSnippet || rssItem.summary || null;
  const rawExcerpt = typeof rawExcerptCandidate === 'string' ? rawExcerptCandidate : null;
  const rawContent = typeof rssItem.content === 'string' ? rssItem.content : null;

  return {
    json: {
      sourceId,
      title,
      url,
      author,
      publishedAt: typeof publishedAt === 'string' ? publishedAt : null,
      rawExcerpt,
      rawContent,
      language: null
    }
  };
}).filter(Boolean);

const stripHtml = (s) => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();

return items.map((item) => {
  const article = item.json;
  const excerpt = stripHtml(article.rawExcerpt).slice(0, 800);
  const content = stripHtml(article.rawContent).slice(0, 1500);

  const userPrompt = [
    `Title: ${article.title}`,
    `Source: ${article.sourceName}`,
    excerpt ? `Excerpt: ${excerpt}` : '',
    content ? `Content: ${content}` : ''
  ].filter(Boolean).join('\n');

  return {
    json: {
      itemId: article.id,
      title: article.title,
      sourceName: article.sourceName,
      excerpt: excerpt,
      content: content,
      ollamaPayload: {
        model: 'qwen3:4b',
        messages: [
          { role: 'system', content: (($('Get Prompts').first().json.prompts || []).find((p) => p.key === 'article_analysis_summary') || {}).content || '' },
          { role: 'user', content: userPrompt }
        ],
        format: 'json',
        stream: false,
        think: false,
        options: { "temperature": 0.2, "num_predict": 1200 }
      }
    }
  };
});

return items.map((item, index) => {
  const ollamaResponse = item.json;
  const src = $('Build Summary Prompt').itemMatching(index).json;
  let parsed;
  try {
    const raw = ollamaResponse?.message?.content;
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    return null;
  }
  if (!parsed || typeof parsed !== 'object') return null;

  return {
    json: {
      itemId: src.itemId,
      title: src.title,
      sourceName: src.sourceName,
      excerpt: src.excerpt,
      content: src.content,
      translatedTitle: String(parsed.translatedTitle || '').slice(0, 500),
      summary: String(parsed.summary || '').slice(0, 900)
    }
  };
}).filter(Boolean);

const tagsList = $('Get Allowed Tags').first().json.tags || [];
const allowedSlugs = tagsList.map((t) => t.slug).join(', ');

return items.map((item) => {
  const data = item.json;
  const userPrompt = [
    `Title: ${data.title}`,
    `Source: ${data.sourceName}`,
    `Summary: ${data.summary}`,
    `allowedTags: ${allowedSlugs}`
  ].join('\n');

  return {
    json: {
      ...data,
      ollamaPayload: {
        model: 'qwen3:4b',
        messages: [
          { role: 'system', content: (($('Get Prompts').first().json.prompts || []).find((p) => p.key === 'article_analysis_tags') || {}).content || '' },
          { role: 'user', content: userPrompt }
        ],
        format: 'json',
        stream: false,
        think: false,
        options: { num_predict: 200, temperature: 0.2 }
      }
    }
  };
});

return items.map((item, index) => {
  const ollamaResponse = item.json;
  const src = $('Build Tags Prompt').itemMatching(index).json;
  let parsed;
  try {
    const raw = ollamaResponse?.message?.content;
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    return null;
  }
  if (!parsed || typeof parsed !== 'object') return null;

  return {
    json: {
      itemId: src.itemId,
      title: src.title,
      sourceName: src.sourceName,
      translatedTitle: src.translatedTitle,
      summary: src.summary,
      tags: Array.isArray(parsed.tags) ? parsed.tags.map((t) => String(t)) : []
    }
  };
}).filter(Boolean);

return items.map((item) => {
  const data = item.json;
  const userPrompt = [
    `Profile: Nicolas Rodriguez, indie Symfony/PHP developer. Goals: improve Symfony/PHP/Docker/AI/automation skills, find freelance opportunities, generate LinkedIn content ideas.`,
    `Title: ${data.title}`,
    `Source: ${data.sourceName}`,
    `Summary: ${data.summary}`,
    `Tags: ${(data.tags || []).join(', ')}`
  ].join('\n');

  return {
    json: {
      ...data,
      ollamaPayload: {
        model: 'qwen3:4b',
        messages: [
          { role: 'system', content: (($('Get Prompts').first().json.prompts || []).find((p) => p.key === 'article_analysis_scoring') || {}).content || '' },
          { role: 'user', content: userPrompt }
        ],
        format: 'json',
        stream: false,
        think: false,
        options: { num_predict: 400, temperature: 0.3 }
      }
    }
  };
});

const parseJsonLenient = (value) => {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return null;

  const text = value.trim();
  if (text === '') return null;

  try {
    return JSON.parse(text);
  } catch (e) {
    // ignore
  }

  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenceMatch && typeof fenceMatch[1] === 'string') {
    const inner = fenceMatch[1].trim();
    if (inner !== '') {
      try {
        return JSON.parse(inner);
      } catch (e) {
        // ignore
      }
    }
  }

  const objStart = text.indexOf('{');
  const objEnd = text.lastIndexOf('}');
  if (objStart !== -1 && objEnd !== -1 && objEnd > objStart) {
    const slice = text.slice(objStart, objEnd + 1);
    try {
      return JSON.parse(slice);
    } catch (e) {
      // ignore
    }
  }

  return null;
};

const clamp = (value) => {
  const n = Number.parseInt(String(value), 10);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 0;
};

return items.map((item, index) => {
  const ollamaResponse = item.json;
  const src = $('Build Scoring Prompt').itemMatching(index).json;
  const raw = ollamaResponse?.message?.content;
  const parsed = parseJsonLenient(raw);
  const parseOk = parsed && typeof parsed === 'object';

  return {
    json: {
      rssItemId: src.itemId,
      translatedTitle: src.translatedTitle,
      summary: src.summary,
      tags: src.tags || [],
      relevanceScore: parseOk ? clamp(parsed.relevanceScore) : 0,
      businessScore: parseOk ? clamp(parsed.businessScore) : 0,
      learningScore: parseOk ? clamp(parsed.learningScore) : 0,
      contentScore: parseOk ? clamp(parsed.contentScore) : 0,
      finalScore: parseOk ? clamp(parsed.finalScore) : 0,
      reasoning: parseOk
        ? String(parsed.reasoning || '')
        : `PARSE_ERROR: invalid JSON scoring output (first 500 chars): ${String(raw || '').slice(0, 500)}`,
      modelUsed: 'qwen3:4b'
    }
  };
});

const pickFirstText = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim() !== '') {
      return value.trim();
    }
  }

  return null;
};

return items.map((item, index) => {
  const original = $('Filter').itemMatching(index).json;
  const extracted = pickFirstText(item.json.articleText, item.json.mainText, item.json.bodyText);

  const rawContent = extracted && extracted.length >= 400 ? extracted : original.rawContent;

  let rawExcerpt = original.rawExcerpt;
  if (typeof rawExcerpt !== 'string' || rawExcerpt.trim() === '') {
    rawExcerpt = typeof rawContent === 'string' && rawContent.trim() !== ''
      ? rawContent.trim().slice(0, 280)
      : null;
  }

  return {
    json: {
      ...original,
      rawContent,
      rawExcerpt,
    },
  };
});
